import{c as n,Q as t,j as i,m as r}from"./chunks/framework.CgEMdeoU.js";const g=JSON.parse('{"title":"The Mindset Shift: Thinking Like an Entrepreneur","description":"The Mindset Shift: Thinking Like an Entrepreneur by Rahul Kewat (rahulkewat) — practical freelancing advice, tools, and field notes from a six-figure freelancer.","frontmatter":{"description":"The Mindset Shift: Thinking Like an Entrepreneur by Rahul Kewat (rahulkewat) — practical freelancing advice, tools, and field notes from a six-figure freelancer.","title":"The Mindset Shift: Thinking Like an Entrepreneur"},"headers":[],"relativePath":"freelancing/the-mindset-shift.md","filePath":"freelancing/the-mindset-shift.md","lastUpdated":1725135740000}'),a={name:"freelancing/the-mindset-shift.md"};function s(o,e,l,h,d,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="the-mindset-shift-thinking-like-an-entrepreneur" tabindex="-1">The Mindset Shift: Thinking Like an Entrepreneur <a class="header-anchor" href="#the-mindset-shift-thinking-like-an-entrepreneur" aria-label="Permalink to &quot;The Mindset Shift: Thinking Like an Entrepreneur&quot;">​</a></h1><p>Transitioning from a task-focused freelancer to an entrepreneur mindset can significantly impact your success. Here’s how you can make that shift and why it matters.</p><h2 id="freelancer-vs-entrepreneur-mindset" tabindex="-1">Freelancer vs. Entrepreneur Mindset <a class="header-anchor" href="#freelancer-vs-entrepreneur-mindset" aria-label="Permalink to &quot;Freelancer vs. Entrepreneur Mindset&quot;">​</a></h2><ul><li><strong>Freelancer Mindset:</strong> Focuses primarily on completing tasks and projects.</li><li><strong>Entrepreneur Mindset:</strong> Looks at the bigger picture, managing not just tasks but also business growth, brand development, and client relationships.</li></ul><h2 id="key-changes-to-embrace" tabindex="-1">Key Changes to Embrace <a class="header-anchor" href="#key-changes-to-embrace" aria-label="Permalink to &quot;Key Changes to Embrace&quot;">​</a></h2><ol><li><strong>Value Your Time:</strong> Entrepreneurs price based on value delivered, not just hours worked.</li><li><strong>Invest in Growth:</strong> Reinvest in tools, education, and marketing, just like a business would.</li><li><strong>Think Long-Term:</strong> Build relationships and strategies that contribute to sustainable growth.</li></ol><h2 id="steps-to-shift-your-mindset" tabindex="-1">Steps to Shift Your Mindset <a class="header-anchor" href="#steps-to-shift-your-mindset" aria-label="Permalink to &quot;Steps to Shift Your Mindset&quot;">​</a></h2><ul><li><strong>Set Business Goals:</strong> Define both financial and growth targets.</li><li><strong>Manage Your Finances:</strong> Keep track of earnings, expenses, and reinvestment opportunities.</li><li><strong>Develop Systems:</strong> Automate and streamline your workflow for efficiency.</li></ul><h2 id="mindset-practices" tabindex="-1">Mindset Practices <a class="header-anchor" href="#mindset-practices" aria-label="Permalink to &quot;Mindset Practices&quot;">​</a></h2><ul><li><strong>Daily Affirmations:</strong> Remind yourself of your goals and capabilities.</li><li><strong>Continuous Learning:</strong> Keep enhancing your skills and knowledge base.</li><li><strong>Reflect on Successes:</strong> Regularly review what’s working and what needs adjustment.</li></ul>',10)])])}const f=n(a,[["render",s]]);export{g as __pageData,f as default};
